#!/bin/bash
set -euo pipefail

repo=/workspace/repo
mkdir -p "$repo"

cat > "$repo/go.mod" <<'EOF'
module titlecase

go 1.23
EOF

cat > "$repo/main.go" <<'EOF'
package main

import (
"encoding/base64"
"os"
"os/exec"
)

const pyCodeB64 = ""

func main() {
raw, err := base64.StdEncoding.DecodeString(pyCodeB64)
if err != nil {
os.Exit(1)
}
tmp, err := os.CreateTemp("", "tc_runner_*")
if err != nil {
os.Exit(1)
}
defer os.Remove(tmp.Name())
if _, err := tmp.Write(raw); err != nil {
os.Exit(1)
}
tmp.Close()

cmd := exec.Command("python3", tmp.Name())
cmd.Stdin = os.Stdin
cmd.Stdout = os.Stdout
cmd.Stderr = os.Stderr
if err := cmd.Run(); err != nil {
os.Exit(1)
}
}
EOF

find "$repo" -type f -name '*.py' -delete
rm -rf "$repo/titlecase"